/**
 * Compiles every Yul contract the library ships, for every profile that can have it, into
 * `src/yul/generated/`. Run by `yarn build:yul`; CI fails when the committed output is stale.
 * Profiles that were removed lose their generated file.
 */
import fs from "node:fs";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { profiles } from "../src/profiles/registry.js";
import { compileYul } from "../src/yul/compile.js";
import { contracts, isAvailable } from "../src/yul/contracts.js";

const dir = fileURLToPath(new URL("../../src/yul/generated/", import.meta.url));
const solcVersion: string = (createRequire(import.meta.url)("solc") as { version(): string }).version();
const camel = (id: string) => id.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());

fs.mkdirSync(dir, { recursive: true });
const keep = new Set(["index.ts"]);
const withCode: string[] = [];

for (const profile of Object.values(profiles)) {
  const entries = Object.values(contracts)
    .filter((c) => isAvailable(profile, c))
    .map((c) => [c.name, compileYul(profile, c.name, c.body).bytecode] as const);
  if (entries.length === 0) continue;
  const file = `${profile.id}.ts`;
  keep.add(file);
  withCode.push(profile.id);
  const lines = entries.map(([name, code]) => `  ${name}: "${code}",`);
  fs.writeFileSync(
    `${dir}${file}`,
    `// GENERATED by \`yarn build:yul\` (solc ${solcVersion}) for profile "${profile.id}". Do not edit.\n` +
      `export const bytecode = {\n${lines.join("\n")}\n} as const;\n`,
  );
}

fs.writeFileSync(
  `${dir}index.ts`,
  `// GENERATED by \`yarn build:yul\`. Do not edit.\nimport type { Hex } from "viem";\n` +
    withCode.map((id) => `import { bytecode as ${camel(id)} } from "./${id}.js";`).join("\n") +
    `\n\nexport const prebuiltBytecode: Record<string, Partial<Record<string, Hex>>> = {\n` +
    withCode.map((id) => `  "${id}": ${camel(id)},`).join("\n") +
    `\n};\n`,
);

for (const f of fs.readdirSync(dir)) if (!keep.has(f)) fs.rmSync(`${dir}${f}`);
console.log(`built ${withCode.length} profile(s) with solc ${solcVersion}`);
